/* Uses the existing player dialog, portraits, save queue, and owner permissions. */
let familyFocus=null,familyBusy=false;
function familyPortrait(n){return n.portrait&&validTeamLogo(n.portrait)?`<img class="family-portrait" src="${n.portrait}" alt="${escapeHTML(n.name)}">`:`<span class="family-portrait">${playerSilhouette()}</span>`}
function familyStatus(n){if(n.deathYear!==undefined)return 'Deceased '+n.deathYear+' · age '+familyAge(n,n.deathYear);if(n.status==='retired')return 'Retired '+n.retiredYear+' · age '+familyAge(n,n.retiredYear);if(n.origin==='historical'&&n.playerId===null)return 'Historical reference · outside this simulated league';return n.status;}
function familyHonors(n){const t=familyTotals(n);return `${t.titles} titles · ${t.allStar} All-Star · ${t.mvp} MVP · ${t.dpoy} DPOY · ${t.roy} ROY${t.hof?' · Hall of Fame':''}`;}
function familyProfileTab({p}){familyCapture();const n=familyForPlayer(p.id);return familyPanel(n.id);}
function familyPanel(id){const n=familyPerson(id);if(!n)return '<p>Family member unavailable.</p>';const members=familyComponent(id),relatives=members.filter(p=>p.id!==id),totals=Object.fromEntries([...FAMILY_TOTAL_KEYS,'hof','pro'].map(k=>[k,members.reduce((a,p)=>a+familyTotals(p)[k],0)]));familyFocus=id;
 return `<section class="family-panel"><h3>Family & relatives</h3><p>${n.origin==='historical'?'Verified historical identity':'Fictional simulation identity'} · ${escapeHTML(n.league)} · Age ${familyAge(n)}${n.birthdateEstimated?' (estimated from legacy records)':''}</p><p>${escapeHTML(familyStatus(n))}${n.lastTeam?' · Last recorded team: '+escapeHTML(n.lastTeam):''}</p><div class="actions"><button onclick="familyTree('${id}')">Family tree</button>${ownerCanManage()?`<button onclick="familyEditor('${id}')">Edit relatives</button>`:''}<button onclick="familyHub()">Family directory & settings</button></div><p class="muted">Totals below cover recorded simulation careers only. Historical reference records do not contribute real-life awards, salaries or statistics. Cross-league relatives retain separate records.</p>${relatives.length?`<div class="family-list">${relatives.map(r=>`<article>${familyPortrait(r)}<div><button class="namebutton" onclick="familyOpen('${r.id}')">${escapeHTML(r.name)}</button><strong>${familyRelationship(id,r.id)||'Extended relative'}</strong><p>Age ${familyAge(r)} · ${escapeHTML(familyStatus(r))} · ${escapeHTML(r.league)}${r.lastTeam?' · '+escapeHTML(r.lastTeam):''}</p><small>${familyHonors(r)}</small></div></article>`).join('')}</div>`:'<p>No relatives recorded. Use Edit relatives to add a connection. Surnames do not establish family ties.</p>'}<h3>Family legacy</h3><p>${totals.pro} members with recorded professional appearances · ${totals.titles} player championships · ${totals.hof} Hall of Fame inductions</p><p>${totals.allStar} All-Star selections · ${totals.mvp} MVP · ${totals.dpoy} DPOY · ${totals.roy} Rookie of the Year</p><div class="scroll" tabindex="0" aria-label="Compare family careers"><table><thead><tr><th>Relative</th><th>League</th><th>GP</th><th>PTS</th><th>REB</th><th>AST</th><th>STL</th><th>BLK</th><th>TOV</th><th>Titles</th><th>All-Star</th><th>MVP</th><th>DPOY</th><th>ROY</th><th>HoF</th></tr></thead><tbody>${members.map(p=>{const t=familyTotals(p);return `<tr><th><button class="namebutton" onclick="familyOpen('${p.id}')">${escapeHTML(p.name)}</button></th><td>${escapeHTML(p.league)}</td>${['gp','pts','reb','ast','stl','blk','tov','titles','allStar','mvp','dpoy','roy','hof'].map(k=>`<td>${t[k].toLocaleString()}</td>`).join('')}</tr>`}).join('')}</tbody></table></div><p class="muted">Player championships count each winning relative separately. Older saves may lack All-Star, ROY, or complete pre-feature career statistics.</p>${n.source?`<p><a href="${escapeHTML(n.source)}" target="_blank" rel="noopener noreferrer">Historical identity source</a></p>`:''}<details><summary>Relationship sources</summary>${familyStore().edges.filter(e=>members.some(n=>n.id===e.a)&&members.some(n=>n.id===e.b)).map(e=>`<p>${escapeHTML(familyPerson(e.a).name)} → ${escapeHTML(familyPerson(e.b).name)} · ${e.origin==='verified'?`<a href="${escapeHTML(e.source)}" target="_blank" rel="noopener noreferrer">Verified reference</a>`:'Custom / simulated relationship'}</p>`).join('')||'<p>No links yet.</p>'}</details></section>`;
}
async function familyLoadHistory(){if(!simulationHeadless()&&activeSaveId&&careerStore?.allArchive)await hydrateLeagueHistory(['statsArchive','hallPeople']);familyImportLegacy(state);}
async function familyOpen(id){try{await familyLoadHistory()}catch(e){toast('Family history could not load: '+e.message);return;}familySync();const n=familyPerson(id);if(!n||!familyVisible(n))return;familyFocus=id;if(n.playerId!==null&&playerContext(n.playerId)){await openPlayerProfile(n.playerId);changePlayerTab('Family');return;}titleModal(escapeHTML(n.name),`${familyPortrait(n)}${familyPanel(id)}`);document.getElementById('profile').classList.add('family-dialog');}
function familyTree(id){familySync();const members=familyComponent(id),f=familyStore(),levels=new Map([[id,0]]),q=[id];while(q.length){const at=q.shift();for(const e of f.edges){const other=e.a===at?e.b:e.b===at?e.a:null;if(!other||levels.has(other)||!members.some(n=>n.id===other))continue;const step=e.type==='parent'||e.type==='avuncular'?1:e.type==='grandparent'?2:0;levels.set(other,levels.get(at)+(e.a===at?step:-step));q.push(other);}}
 const shown=members.sort((a,b)=>(Math.abs(levels.get(a.id)||0)-Math.abs(levels.get(b.id)||0))||a.birthdate.localeCompare(b.birthdate)).slice(0,40),min=Math.min(0,...shown.map(n=>levels.get(n.id)||0)),slots={},positions=new Map();for(const n of shown){const level=(levels.get(n.id)||0)-min,index=slots[level]||0;slots[level]=index+1;positions.set(n.id,{x:20+index*220,y:20+level*180});}const width=Math.max(420,...Object.values(slots).map(n=>n*220+20)),height=Math.max(200,...[...positions.values()].map(p=>p.y+160));
 titleModal('Family tree',`<p>Lines connect recorded relationships. Choose a member to open their profile, then use Family tree to refocus. Scroll horizontally on smaller screens.</p><button onclick="familyOpen('${id}')">Back to ${escapeHTML(familyPerson(id).name)}</button>${members.length>40?'<p>Showing 40 nearby members. Open another member to navigate farther, or search the family directory.</p>':''}<div class="family-tree-scroll" tabindex="0" role="region" aria-label="Interactive family tree"><div class="family-tree" style="width:${width}px;height:${height}px"><svg width="${width}" height="${height}" aria-hidden="true">${f.edges.filter(e=>positions.has(e.a)&&positions.has(e.b)).map(e=>{const a=positions.get(e.a),b=positions.get(e.b);return `<line x1="${a.x+100}" y1="${a.y+70}" x2="${b.x+100}" y2="${b.y+70}"/><text x="${(a.x+b.x)/2+100}" y="${(a.y+b.y)/2+60}">${escapeHTML(e.type)}</text>`}).join('')}</svg>${shown.map(n=>{const p=positions.get(n.id);return `<button class="family-tree-node ${n.id===id?'family-selected':''}" style="left:${p.x}px;top:${p.y}px" onclick="familyOpen('${n.id}')">${familyPortrait(n)}<strong>${escapeHTML(n.name)}</strong><small>${familyRelationship(id,n.id)|| (n.id===id?'Selected person':'Extended relative')} · Age ${familyAge(n)}</small></button>`}).join('')}</div></div>`);document.getElementById('profile').classList.add('family-dialog');
}
function familySearchResults(query='',select=false){const f=familySync(),needle=query.toLowerCase().trim(),list=f.people.filter(n=>familyVisible(n)&&n.id!== (select?familyFocus:null)&&n.name.toLowerCase().includes(needle)),shown=list.slice(0,50);return `${list.length>50?'<p>Showing the first 50 matches. Type a name to narrow the list.</p>':''}${shown.map(n=>`<button type="button" class="family-search-result" onclick="${select?'familyChoose':'familyOpen'}('${n.id}')">${escapeHTML(n.name)} · ${escapeHTML(n.league)} · ${escapeHTML(familyStatus(n))}</button>`).join('')||'<p>No matches in this season.</p>'}`;}
function familySearch(input,select){document.getElementById('family-search-results').innerHTML=familySearchResults(input.value,select)}
async function familyHub(){try{await familyLoadHistory()}catch(e){toast('Family history could not load: '+e.message);return;}familySync();familyCapture();const settings=familyStore().settings;titleModal('Families & basketball legacies',`<p>Browse active players, retired players, fictional family members and verified historical references. References born after this season remain hidden and never enter rosters automatically.</p><label>Search family members<input type="search" oninput="familySearch(this,false)" placeholder="Player or relative name"></label>${ownerCanManage()?`<details><summary>Family simulation settings</summary><form onsubmit="familySaveSettings(event)"><label><input type="checkbox" name="generate" ${settings.generate?'checked':''}> Generate fictional children during season progression</label><label><input type="checkbox" name="allowHistoricalFiction" ${settings.allowHistoricalFiction?'checked':''}> Allow fictional relatives for verified historical players</label><p>Existing children keep aging when generation is disabled. Simulated births and development are game assumptions, not demographic or genetic predictions.</p><button>Save family settings</button></form></details>`:''}<div id="family-search-results">${familySearchResults()}</div>`);document.getElementById('profile').classList.add('family-dialog');}
async function familyCommit(action,done){if(familyBusy||!ownerCanManage())return;const original=state,before=copy(state),saveId=activeSaveId;familyBusy=true;try{action();if(await save()===false)throw Error('Family changes could not be saved.');if(state===original&&activeSaveId===saveId){toast('Family changes saved');done?.();}}catch(e){if(state===original&&activeSaveId===saveId)state=before;toast(e.message);}finally{familyBusy=false;}}
function familySaveSettings(event){event.preventDefault();const e=event.currentTarget.elements;familyCommit(()=>{familyStore().settings={generate:e.generate.checked,allowHistoricalFiction:e.allowHistoricalFiction.checked};},familyHub)}
const FAMILY_EDIT_OPTIONS=[['parent','Parent (father / mother)'],['child','Child (son / daughter)'],['sibling','Sibling (brother / sister)'],['half','Half-sibling'],['cousin','Cousin'],['uncle','Uncle / aunt'],['nephew','Nephew / niece'],['grandparent','Grandfather / grandmother'],['grandchild','Grandson / granddaughter']];
function familyApplyChoice(id,target,choice,replace=false){let a=id,b=target,type=choice;if(['parent','uncle','grandparent'].includes(choice)){a=target;b=id;}if(['child','parent'].includes(choice))type='parent';if(['uncle','nephew'].includes(choice))type='avuncular';if(['grandchild','grandparent'].includes(choice))type='grandparent';familySetEdge(a,b,type,state,replace);}
function familyEditor(id){if(!ownerCanManage())return;familySync();familyFocus=id;const n=familyPerson(id);titleModal('Edit relatives — '+escapeHTML(n.name),`<p>Choose how the selected person is related to ${escapeHTML(n.name)}. Changes apply to both profiles. Editing verified links marks the replacement as custom. Relationships inferred from shared parents change when those parent connections are edited.</p><button onclick="familyOpen('${id}')">Back to profile</button><form onsubmit="familySaveEdge(event,'${id}')"><label>Search existing players or relatives<input type="search" oninput="familySearch(this,true)"></label><div id="family-search-results">${familySearchResults('',true)}</div><input type="hidden" name="relative" required><p id="family-chosen" role="status">Choose a relative above.</p><label>Relationship<select name="relationship">${FAMILY_EDIT_OPTIONS.map(([v,label])=>`<option value="${v}">${label}</option>`).join('')}</select></label><label><input type="checkbox" name="replace"> Replace the existing relationship for this pair</label><button>Save relationship</button></form><h3>Recorded connections</h3>${familyStore().edges.filter(e=>e.a===id||e.b===id).map(e=>{const other=e.a===id?e.b:e.a,n=familyPerson(other);return familyVisible(n)?`<p>${escapeHTML(n.name)} · ${familyRelationship(id,other)} <button onclick="familyRemoveUI('${id}','${other}')">Remove relationship</button></p>`:''}).join('')||'<p>No direct connections.</p>'}<details><summary>Create a fictional relative</summary><form onsubmit="familyCreateUI(event,'${id}')"><label>Name<input name="personName" maxlength="80" required></label><label>Birth date<input name="birthdate" type="date" max="${state.year}-10-01" required></label><label>Gender<select name="gender"><option value="male">Male</option><option value="female">Female</option></select></label><label>League affiliation<select name="league"><option>NBA</option><option>WNBA</option><option>Other</option></select></label><label>Relationship<select name="relationship">${FAMILY_EDIT_OPTIONS.map(([v,label])=>`<option value="${v}">${label}</option>`).join('')}</select></label><label><input type="checkbox" name="basketball"> Give this fictional relative a developing basketball pathway</label><p>Development is independent. A pathway does not guarantee a draft place or professional career. No contract or roster spot is created here.</p><button>Create and connect relative</button></form></details>${!familyPlayers().some(p=>p.id===n.playerId)?`<details><summary>Record life status</summary><form onsubmit="familyLifeUI(event,'${id}')"><label>Death year (leave blank for living)<input name="deathYear" type="number" min="${Number(n.birthdate.slice(0,4))}" max="${state.year}" value="${n.deathYear??''}"></label><button>Save life status</button></form></details>`:''}${n.playerId!==null&&n.origin!=='historical'?`<details><summary>Assign a verified historical identity</summary><p>This explicitly changes this player’s name, birth date and age and connects the verified family. Ratings, contracts and simulated accomplishments remain unchanged; they are not real-life historical records.</p><form onsubmit="familyBindUI(event,${n.playerId})"><select name="historicalId">${familyStore().people.filter(p=>p.origin==='historical'&&p.playerId===null&&p.gender===n.gender&&familyAge(p)>=18&&familyAge(p)<=60).map(p=>`<option value="${p.historicalId}">${escapeHTML(p.name)} · ${p.birthdate}</option>`).join('')}</select><label><input type="checkbox" name="confirm" required> Apply this historical identity to this player</label><button>Apply identity and verified family</button></form></details>`:''}`);document.getElementById('profile').classList.add('family-dialog');}
function familyChoose(id){const n=familyPerson(id),form=document.querySelector('#family-chosen').closest('form');form.elements.relative.value=id;document.getElementById('family-chosen').textContent='Selected: '+n.name;}
function familySaveEdge(event,id){event.preventDefault();const e=event.currentTarget.elements,target=e.relative.value,choice=e.relationship.value,replace=e.replace.checked;familyCommit(()=>familyApplyChoice(id,target,choice,replace),()=>familyEditor(id));}
function familyRemoveUI(id,other){familyCommit(()=>familyRemoveEdge(id,other),()=>familyEditor(id));}
function familyCreateUI(event,id){event.preventDefault();const e=event.currentTarget.elements,v={name:e.personName.value,birthdate:e.birthdate.value,gender:e.gender.value,league:e.league.value},choice=e.relationship.value,basketball=e.basketball.checked;familyCommit(()=>{if(familyPerson(id).origin==='historical'&&!familyStore().settings.allowHistoricalFiction)throw Error('Enable fictional relatives for historical players in Family simulation settings first.');const n=familyCreatePerson(v);if(basketball){n.origin='generated';n.pathway='basketball';n.ovr=rand(35,60);n.pot=Math.max(n.ovr,rand(50,95));n.height=n.gender==='female'?rand(65,78):rand(72,86);n.attributes={};}familyApplyChoice(id,n.id,choice);},()=>familyEditor(id));}
function familyLifeUI(event,id){event.preventDefault();const value=event.currentTarget.elements.deathYear.value;familyCommit(()=>{const n=familyPerson(id);if(value===''){delete n.deathYear;n.status='non-player';return;}const year=Number(value);if(!Number.isInteger(year)||year<Number(n.birthdate.slice(0,4))||year>state.year)throw Error('Enter a valid death year.');n.deathYear=year;n.status='deceased';for(const e of familyStore().edges)familyValidateEdge(familyStore(),e);},()=>familyEditor(id));}
function familyBindUI(event,id){event.preventDefault();const e=event.currentTarget.elements;if(!e.confirm.checked)return;const historicalId=e.historicalId.value;familyCommit(()=>familyBind(id,historicalId),()=>familyOpen(familyForPlayer(id).id));}
PLAYER_TABS.push('Family');
const familyOverviewBefore=playerOverview;playerOverview=function(ctx){familySync();const n=familyForPlayer(ctx.p.id),count=familyComponent(n.id).length-1;return familyOverviewBefore(ctx)+playerCard('FAMILY & RELATIVES',`<p>${count?count+' recorded family member'+(count===1?'':'s'):'No relatives recorded yet.'}</p><button onclick="changePlayerTab('Family')">View family & legacy</button>`);};
const familyDirectoryBefore=playersDirectoryTable;playersDirectoryTable=function(){return '<div class="note"><button onclick="familyHub()">Families & basketball legacies</button></div>'+familyDirectoryBefore();};

const familyTabBefore=changePlayerTab;changePlayerTab=function(tab){if(tab!=='Family')return familyTabBefore(tab);const id=activePlayerId,career=state;return familyLoadHistory().then(()=>{if(activePlayerId===id&&state===career)return familyTabBefore(tab)}).catch(e=>toast('Family history could not load: '+e.message));};
